  assert.deepStrictEqual(
    warnings.map((w) => w.counterpart).sort(),
    [
      "pages/src/content/docs/ja/faq.md",
      "pages/src/content/docs/ko/faq.md",
      "pages/src/content/docs/ru/faq.md",
      "pages/src/content/docs/zh/faq.md",
