const assert = require("assert");
const fs = require("fs");
const os = require("os");
const path = require("path");
const {
  LINK_ALLOW_MARKER,
  MARKETPLACES,
  MIN_EXPECTED_LINKS,
  PLUGIN_DECLARATIONS,
  SKILL_ROOTS,
  COMMAND_DIRS,
  escapeAnnotationData,
  emitAnnotation,
  walkTextFiles,
  checkCorpusFloor,
  stripTrailingPunctuation,
  toRepoPath,
  extractRepoLinks,
  validateRepoLinks,
  parseFrontmatter,
